mkitem!{mkstruct!{#[doc = " A reference to an instance of an abstract \"counter\" that will yield a value in a coverage"] #[doc = " report. Note that `id` has different interpretations, depending on the `kind`:"] #[doc = "   * For `CounterKind::Zero`, `id` is assumed to be `0`"] #[doc = "   * For `CounterKind::CounterValueReference`,  `id` matches the `counter_id` of the injected"] #[doc = "     instrumentation counter (the `index` argument to the LLVM intrinsic"] #[doc = "     `instrprof.increment()`)"] #[doc = "   * For `CounterKind::Expression`, `id` is the index into the coverage map's array of"] #[doc = "     counter expressions."] #[doc = ""] #[doc = " Corresponds to struct `llvm::coverage::Counter`."] #[doc = ""] #[doc = " Must match the layout of `LLVMRustCounter`."] #[derive (Copy , Clone , Debug)] #[repr (C)] pub (crate) struct Counter { pub (crate) kind : CounterKind , id : u32 , }}}
mkitem!{mkimpl!{impl Counter { #[doc = " A `Counter` of kind `Zero`. For this counter kind, the `id` is not used."] pub (crate) const ZERO : Self = Self { kind : CounterKind :: Zero , id : 0 } ; #[doc = " Constructs a new `Counter` of kind `CounterValueReference`."] pub (crate) fn counter_value_reference (counter_id : CounterId) -> Self { Self { kind : CounterKind :: CounterValueReference , id : counter_id . as_u32 () } } #[doc = " Constructs a new `Counter` of kind `Expression`."] pub (crate) fn expression (expression_id : ExpressionId) -> Self { Self { kind : CounterKind :: Expression , id : expression_id . as_u32 () } } pub (crate) fn from_term (term : CovTerm) -> Self { match term { CovTerm :: Zero => Self :: ZERO , CovTerm :: Counter (id) => Self :: counter_value_reference (id) , CovTerm :: Expression (id) => Self :: expression (id) , } } }}}
